"""Выгрузка бинарных данных Salt and Sanctuary в JSON (только чтение папки игры).
Форматы взяты из декомпиляции (BinaryReader: int32/float32 LE, string = 7bit-len + UTF8, bool = 1 байт).
Языки: 13 слотов, 0 = английский.  Запуск: python tools/export_data.py [папка_игры] [папка_вывода]
"""
import json, struct, sys, os

GAME = sys.argv[1] if len(sys.argv) > 1 else "C:/Program Files (x86)/Steam/steamapps/common/Salt and Sanctuary"
OUT = sys.argv[2] if len(sys.argv) > 2 else os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "data")
LANG = 13


class R:
    def __init__(s, b): s.b, s.p = b, 0
    def i(s): v = struct.unpack_from("<i", s.b, s.p)[0]; s.p += 4; return v
    def f(s): v = struct.unpack_from("<f", s.b, s.p)[0]; s.p += 4; return round(v, 6)
    def o(s): v = s.b[s.p] != 0; s.p += 1; return v
    def s(s):
        n = sh = 0
        while True:
            c = s.b[s.p]; s.p += 1; n |= (c & 0x7F) << sh; sh += 7
            if c < 0x80: break
        v = s.b[s.p:s.p + n].decode("utf-8"); s.p += n; return v
    def end(s): return s.p == len(s.b)


def load(rel):
    with open(os.path.join(GAME, rel), "rb") as fh: return R(fh.read())


# (кол-во values, кол-во upgradePath) по категории — LootDef.SetCategory
CAT = {0: (25, 2), 1: (13, 2), 2: (12, 2), 3: (2, 2), 4: (1, 1), 5: (3, 1), 6: (1, 1), 7: (1, 1)}
CATNAME = ["weapon", "shield", "armor", "ring", "consumable", "magic", "key", "material"]


def loot(r):
    cats = []
    for _ in range(8):
        items = []
        for _ in range(r.i()):
            d = {"name": r.s()}
            d["title"], d["desc"] = [], []
            for _ in range(LANG): d["title"].append(r.s()); d["desc"].append(r.s())
            d["texture"] = r.s(); d["category"] = r.i(); d["type"] = r.i(); d["upgrade"] = r.i()
            d["upgradeFac"] = r.f(); d["flags"] = r.i(); d["weight"] = r.f(); d["special"] = r.i()
            d["img"] = r.i(); d["value"] = r.f(); d["durability"] = r.f()
            nv, nu = CAT[d["category"]]
            d["values"] = [r.f() for _ in range(nv)]
            d["upgradePath"] = []
            for _ in range(nu):
                if r.o():
                    a = r.s(); c = r.i(); b = r.s(); co = r.i()
                    d["upgradePath"].append({"req": a, "reqCount": c, "out": b, "cost": co})
            items.append(d)
        cats.append(items)
    return cats


MON_STR1 = ["def", "texture", "helm", "armor", "gloves", "boots", "weapon", "shield", "stepSnd", "jabSnd",
            "fierceSnd", "hitSnd", "growlSnd", "laughSnd", "dieSnd", "screamSnd"]
MON_INT1 = ["hair", "hairColor", "beard", "beardColor", "skinIdx", "skinClass", "eyes"]
MON_F = ["hp", "attack", "defense", "poise", "stamina", "poiseAttack", "blockReduce", "blockDeflect",
         "blockDmgReduce", "blockMagReduce", "runSpeed", "fireDef", "litDef", "bladedDef", "poisonDef",
         "holyDef", "darkDef"]
MON_ANIM = ["attackAnim", "strongAnim", "specialAnim"]
MON_ANIM2 = ["idleAnim", "runAnim", "runStartAnim", "runEndAnim", "blockAnim", "blockInAnim", "blockOutAnim",
             "blockAdvAnim", "blockRetAnim", "blockAbsAnim"]


def monsters(r):
    out = []
    for _ in range(r.i()):
        d = {"name": r.s()}
        d["title"] = [r.s() for _ in range(LANG)]; d["desc"] = [r.s() for _ in range(LANG)]
        d["boxWidth"] = r.i(); d["boxHeight"] = r.i(); d["phaseThresh"] = r.f(); d["crazeThresh"] = r.f()
        for k in MON_STR1: d[k] = r.s()
        for k in MON_INT1: d[k] = r.i()
        for k in MON_F: d[k] = r.f()
        for k in ("salt", "ai", "type", "flags"): d[k] = r.i()
        d["giant"] = r.o(); d["hover"] = r.o(); d["creature"] = r.i()
        d["slowBack"] = r.o(); d["bestiary"] = r.o(); d["fadeLayer"] = r.o()
        for k in MON_ANIM: d[k] = r.s()
        for k in ("attackReach", "strongReach", "specialReach"): d[k] = r.i()
        for k in MON_ANIM2: d[k] = r.s()
        d["drops"] = []
        for _ in range(6):
            rate = r.f(); item = r.s(); cnt = r.i()
            if item: d["drops"].append({"rate": rate, "loot": item, "count": cnt})
        out.append(d)
    return out


def skilltree(rc, re):
    def nodes(r):
        res = []
        for idx in range(r.i()):
            d = {"id": idx, "name": r.s()}
            d["title"] = [r.s() for _ in range(LANG)]; d["desc"] = [r.s() for _ in range(LANG)]
            d["baseDesc"] = [r.s() for _ in range(LANG)]
            d["type"] = r.i(); d["value"] = r.i(); d["cost"] = r.i()
            d["parent"] = [r.i(), r.i()]; d["loc"] = [r.f(), r.f()]; d["img"] = r.i()
            res.append(d)
        return res
    c = nodes(rc)
    imgs = [{"img": rc.i(), "loc": [rc.f(), rc.f()], "rot": rc.f(), "scale": [rc.f(), rc.f()]} for _ in range(rc.i())]
    return {"classic": c, "enhanced": nodes(re), "imgs": imgs}


def strings(r):
    return [{"key": r.s(), "text": [r.s() for _ in range(LANG)]} for _ in range(r.i())]


def dump(name, obj):
    os.makedirs(OUT, exist_ok=True)
    with open(os.path.join(OUT, name), "w", encoding="utf-8") as f: json.dump(obj, f, ensure_ascii=False, indent=1)


def check(r, what):
    print(f"{what}: {'OK, весь файл прочитан' if r.end() else 'ОСТАТОК %d байт' % (len(r.b) - r.p)}")

