using System.IO;
using LootEdit;
namespace DialogEdit.dialog;
public class NodeOption
{
	public string[] text;
	public string action;
	public string coopAction;
	public NodeOption()
	{
		text = new string[13];
		for (int i = 0; i < text.Length; i++)
		{
			text[i] = "";
		}
		action = "";
		coopAction = "";
	}
	public NodeOption(NodeOption nodeOption)
	{
		text = new string[nodeOption.text.Length];
		for (int i = 0; i < text.Length; i++)
		{
			text[i] = nodeOption.text[i];
		}
		action = nodeOption.action;
		coopAction = nodeOption.coopAction;
	}
	internal void Write(BinaryWriter writer)
	{
		for (int i = 0; i < 13; i++)
		{
			if (i < text.Length)
			{
				writer.Write(text[i]);
			}
			else
			{
				writer.Write(text[0] + " - " + TranslationMgr.GetLangStrFromIdx(i));
			}
		}
		writer.Write(action);
		writer.Write(coopAction);
	}
	internal void Read(BinaryReader reader)
	{
		for (int i = 0; i < text.Length; i++)
		{
			text[i] = reader.ReadString();
		}
		action = reader.ReadString();
		coopAction = reader.ReadString();
	}
}
using System.IO;
using LootEdit.loot;
using ProjectTower.player;
namespace DialogEdit.dialog;
public class NPCDialog
{
	public string name;
	public DialogNode[] nodeList;
	public int rune;
	internal void Read(BinaryReader reader)
	{
		name = reader.ReadString();
		rune = -1;
		int num = reader.ReadInt32();
		InvLoot invLoot = new InvLoot();
		nodeList = new DialogNode[num];
		for (int i = 0; i < num; i++)
		{
			nodeList[i] = new DialogNode();
			nodeList[i].Read(reader);
			if (nodeList[i].giveScript == null)
			{
				continue;
			}
			string[] giveScript = nodeList[i].giveScript;
			foreach (string text in giveScript)
			{
				invLoot.InitFromName(text);
				if (invLoot != null && invLoot.category == 3 && LootCatalog.category[invLoot.category].loot[invLoot.catalogIdx].type == 2)
				{
					rune = LootCatalog.category[invLoot.category].loot[invLoot.catalogIdx].flags;
				}
			}
		}
	}
	internal int GetNodeIdx(string p)
	{
		for (int i = 0; i < nodeList.Length; i++)
		{
			if (nodeList[i].name == p)
			{
				return i;
			}
		}
		return -1;
	}
}
