public static void ReadLocText()
{
	GameConsole.WriteLine("Reading loc text...");
	BinaryReader binaryReader = new BinaryReader(File.Open("dialog/data/strings.ztx", FileMode.Open, FileAccess.Read));
	ReadLocText(binaryReader);
	binaryReader.Close();
	GameConsole.WriteLine("Read loc text.");
	locStringsLoaded = true;
	BottomRightMessage.Init();
}

public static void ReadLocText(BinaryReader reader)
{
	locStrings = new List<LocPair>();
	int num = reader.ReadInt32();
	for (int i = 0; i < num; i++)
	{
		LocPair locPair = new LocPair(reader.ReadString());
		for (int j = 0; j < 13; j++)
		{
			locPair.locStr[j] = reader.ReadString();
		}
		locStrings.Add(locPair);
	}
}

public static void WriteLocText(BinaryWriter writer)
{
	writer.Write(locStrings.Count);
	foreach (LocPair locString in locStrings)
	{
		writer.Write(locString.orig);
		for (int i = 0; i < 13; i++)
		{
			if (i < locString.locStr.Length)
			{
				writer.Write((locString.locStr[i] == null) ? "" : locString.locStr[i]);
			}
			else
			{
				writer.Write(locString.locStr[0] + " - " + TranslationMgr.GetLangStrFromIdx(i));
			}
		}
	}
}

public static void Read(BinaryReader reader, bool isEnhanced = false)
{
	int num = reader.ReadInt32();
	if (isEnhanced)
	{
		dialogList = (enhancedDialog = new NPCDialog[num]);
	}
	else
	{
		dialogList = (classicDialog = new NPCDialog[num]);
	}
	for (int i = 0; i < num; i++)
	{
		dialogList[i] = new NPCDialog();
		dialogList[i].Read(reader);
	}
}

