			ugcPackageIdx = point.X;
			ugcSheetIdx = point.Y;
		}
		if (isLoaded)
		{
			return true;
		}
		if (isLoading)
		{
			return false;
		}
		if (StorageJobMgr.busy)
		{
			return false;
		}
		if (StorageJobMgr.timeOut > 0f)
		{
			return false;
		}
		isLoading = true;
		isLoaded = false;
